const SendCommandSchema = z
  .strictObject({
    GroupId: z.uuid().exactOptional().openapi({ description: 'Gets the group identifier.' }),
    PlaylistItemId: z
      .uuid()
      .exactOptional()
      .openapi({ description: 'Gets the playlist identifier of the playing item.' }),
    When: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Gets or sets the UTC time when to execute the command.' }),
    PositionTicks: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .nullable()
      .exactOptional()
      .openapi({
        type: ['integer', 'null'],
        format: 'int64',
        description: 'Gets the position ticks.',
      }),
    Command: SendCommandTypeSchema.exactOptional().openapi({ description: 'Gets the command.' }),
    EmittedAt: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Gets the UTC time when this command has been emitted.' }),
  })
  .openapi({ description: 'Class SendCommand.', required: [] })
  .openapi('SendCommand')

