export const postVideosMergeVersionsRoute = createRoute({
  method: 'post',
  path: '/Videos/MergeVersions',
  tags: ['Video'],
  summary: 'Merges videos into a single record.',
  operationId: 'MergeVersions',
  request: {
    query: z.object({
      ids: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.uuid()),
        )
        .openapi({
          param: {
            name: 'ids',
            in: 'query',
            description: 'Item id list. This allows multiple, comma delimited.',
            required: true,
            schema: { type: 'array', items: { type: 'string', format: 'uuid' } },
          },
        }),
    }),
  },
  responses: {
    204: { description: 'Videos merged.' },
    400: {
      description: 'Supply at least 2 video ids.',
      content: {
        'application/json': { schema: ProblemDetailsSchema },
        'application/json; profile="CamelCase"': { schema: ProblemDetailsSchema },
        'application/json; profile="PascalCase"': { schema: ProblemDetailsSchema },
      },
    },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden' },
    503: {
      description: 'The server is currently starting or is temporarily not available.',
      content: {},
      headers: z.object({
        'Retry-After': {
          description: 'A hint for when to retry the operation in full seconds.',
          schema: z
            .int32()
            .exactOptional()
            .openapi({
              description: 'A hint for when to retry the operation in full seconds.',
              param: { required: false },
            }),
        },
        Message: {
          description: 'A short plain-text reason why the server is not available.',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              description: 'A short plain-text reason why the server is not available.',
              param: { required: false },
            }),
        },
      }),
    },
  },
  security: [{ CustomAuthentication: ['RequiresElevation'] }],
})

